const iniciosRecientes = `-- name: IniciosRecientes :many
SELECT x.empresa_id::bigint AS empresa_id, x.cuando::timestamptz AS cuando FROM (
    SELECT a.empresa_id, coalesce(a.enviado_en, a.created_at) AS cuando
    FROM mensajeria.avisos a
    WHERE a.canal_id = $1 AND a.destino = $2 AND a.estado IN ('en_cola', 'entregado') AND a.enviado_en IS NOT NULL
      AND a.enviado_en >= $3
    UNION ALL
    SELECT c.empresa_id, m.creado_en AS cuando
    FROM mensajeria.conversacion_mensajes m JOIN mensajeria.conversaciones c ON c.id = m.conversacion_id
    WHERE c.canal_id = $1 AND c.numero = $2 AND m.direccion = 'saliente' AND m.plantilla IS NOT NULL
      AND m.autor_id IS NOT NULL AND m.creado_en >= $3 AND c.empresa_id IS NOT NULL
) x
ORDER BY x.cuando DESC
LIMIT 20
`

type IniciosRecientesParams struct {
	CanalID *int64
	Numero  *string
	Desde   *time.Time
}

type IniciosRecientesRow struct {
	EmpresaID int64
	Cuando    time.Time
}

// Empresas que empezaron una conversación con ese número por ese canal: avisos enviados y
// plantillas mandadas por una persona (iniciar), desde @desde, la más reciente primero.
func (q *Queries) IniciosRecientes(ctx context.Context, arg IniciosRecientesParams) ([]IniciosRecientesRow, error) {
	rows, err := q.db.Query(ctx, iniciosRecientes, arg.CanalID, arg.Numero, arg.Desde)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []IniciosRecientesRow
	for rows.Next() {
		var i IniciosRecientesRow
		if err := rows.Scan(&i.EmpresaID, &i.Cuando); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

